"""Validation for a Peg's published renderers.

A Peg's ``renderers`` block — how its data looks when Workpeg AI shows it —
is authored in ``workpeg.json`` beside ``search`` and ``actions``::

    {
      "renderers": [{
        "view": "summary",
        "title": "Invoice summary",
        "description": "A one-line summary of an invoice."
      }]
    }

A renderer is addressed ``namespace:view`` — the namespace comes from the
Peg, so only the view name is declared here. The intended shape is that the
platform sends ``{namespace, view, data}`` and the Peg's compiled app answers
with a node document, validated by :mod:`workpeg.ui.render_nodes` before
anything renders it.

**Nothing calls a renderer yet, and this paragraph is the honest version of
the one it replaces** (which described that exchange in the present tense).
The block is declared, validated and published exactly as documented, and the
platform has no code that resolves ``namespace:view`` against it — so a
renderer a Peg publishes today is never invoked. The API's emitter for the
frame was removed rather than left implying otherwise (PRD 7.9); what is
missing is the reader on that side, not an emitter.

This module and the manifest block are a RELEASED CONTRACT (0.121.0) and stay
supported unchanged: dormant, not deprecated. Declaring a renderer costs
nothing and will start working without a manifest change.

**Renderers are stateless per step.** The activity drawer rebuilds its body
on every stream frame, so a control that held state would lose it on the next
one — silently, and only sometimes, which is the worst way for a thing to
break. That is a platform constraint rather than a preference, so it is
declared here: a renderer says what it shows, never what it remembers.

Everything is untrusted, for the same reason as ``actions``: it is read off a
CDN into a person's screen. Lengths are capped and control characters
refused.
"""
import re

KEYS = ("view", "title", "description")
REQUIRED = ("view",)

#: How many views one Peg may publish. Each is a name the platform may be
#: asked to render; the ceiling is about the size of a manifest, not storage.
MAX_RENDERERS = 16

MAX_VIEW = 64
MAX_TITLE = 80
MAX_DESCRIPTION = 200

#: A view name. Lowercase and plain, because it is half of an address
#: (``namespace:view``) and the other half is already a slug.
_VIEW_RE = re.compile(r"[a-z][a-z0-9_]{0,63}\Z")

#: C0/C1 controls except tab and newline.
_CONTROL_RE = re.compile(r"[\x00-\x08\x0b-\x1f\x7f-\x9f]")


class RendererValidationError(ValueError):
    """A ``renderers`` block the platform would refuse, or should."""


def _text(value, key, cap, where):
    if not isinstance(value, str) or not value.strip():
        raise RendererValidationError(
            f"{where}: {key} must be a non-empty string")
    if _CONTROL_RE.search(value):
        raise RendererValidationError(
            f"{where}: {key} contains control characters")
    if len(value) > cap:
        raise RendererValidationError(
            f"{where}: {key} is {len(value)} characters; the limit is {cap}")
    return value


def validate(block) -> list:
    """Validate a ``renderers`` block and return the declared views."""
    if not isinstance(block, list):
        raise RendererValidationError(
            "the 'renderers' block in workpeg.json must be a list")
    if len(block) > MAX_RENDERERS:
        raise RendererValidationError(
            f"{len(block)} renderers declared; the limit is {MAX_RENDERERS}")

    out, seen = [], set()
    for index, entry in enumerate(block):
        where = f"renderers[{index}]"
        if not isinstance(entry, dict):
            raise RendererValidationError(f"{where}: must be an object")

        unknown = sorted(set(entry) - set(KEYS))
        if unknown:
            raise RendererValidationError(
                f"{where}: unexpected key(s) {', '.join(unknown)} — only "
                f"{', '.join(KEYS)} are read")
        missing = [key for key in REQUIRED if key not in entry]
        if missing:
            raise RendererValidationError(
                f"{where}: missing required key(s) {', '.join(missing)}")

        view = _text(entry["view"], "view", MAX_VIEW, where)
        if not _VIEW_RE.fullmatch(view):
            raise RendererValidationError(
                f"{where}: view {view!r} must be lowercase letters, digits "
                f"and underscores — it is half of an address, and the other "
                f"half is already a slug")
        if view in seen:
            raise RendererValidationError(
                f"{where}: {view!r} is declared twice; a view name addresses "
                f"one renderer")
        seen.add(view)

        declared = {"view": view}
        if "title" in entry:
            declared["title"] = _text(entry["title"], "title", MAX_TITLE,
                                      where)
        if "description" in entry:
            declared["description"] = _text(
                entry["description"], "description", MAX_DESCRIPTION, where)
        out.append(declared)
    return out
